arguments.content:
* {
    all: initial;
}

window#waybar {
    background-color: rgba(20, 20, 30, 0.95);
    color: #ffffff;
    font-family: "JetBrains Mono Nerd Font", monospace;
    font-size: 14px;
    border-radius: 12px;
}

#workspaces {
    margin: 0 8px;
}

#workspaces > button {
    padding: 6px 12px;
    margin: 0 4px;
    border-radius: 999px;
    background-color: rgba(50, 50, 70, 0.8);
    color: #ffffff;
}

#workspaces > button:hover {
    background-color: rgba(100, 100, 150, 0.9);
}

#workspaces > button.active {
    background-color: rgba(70, 130, 180, 0.95);
    font-weight: bold;
}

#workspaces > button.empty {
    opacity: 0.4;
}

#window {
    padding: 6px 12px;
    margin: 0 8px;
    background-color: rgba(30, 30, 45, 0.9);
    border-radius: 999px;
}

#submap {
    padding: 6px 12px;
    margin: 0 8px;
    background-color: rgba(30, 30, 45, 0.9);
    border-radius: 999px;
}

#language {
    padding: 6px 12px;
    margin: 0 8px;
    background-color: rgba(30, 30, 45, 0.9);
    border-radius: 999px;
}

#clock {
    padding: 6px 12px;
    margin: 0 8px;
    background-color: rgba(30, 30, 45, 0.9);
    border-radius: 999px;
}

